import * as THREE from 'three';

/**
 * Builds a simple "lantern" scene graph:
 *
 *   lantern (Group)
 *     ├─ pole   (CylinderGeometry)
 *     ├─ housing (BoxGeometry)
 *     └─ bulb   (SphereGeometry)
 *
 * Each part gets a distinct position and its own MeshStandardMaterial color,
 * so every stage of the round trip can be verified independently.
 */
export function buildLantern() {
  const root = new THREE.Group();
  root.name = 'lantern';

  // Pole: vertical shaft rising from y = 0 to y = 2.
  const poleGeo = new THREE.CylinderGeometry(0.08, 0.1, 2, 12);
  const poleMat = new THREE.MeshStandardMaterial({
    name: 'PoleMaterial',
    color: new THREE.Color(0.35, 0.38, 0.42), // dark steel gray
    metalness: 0.8,
    roughness: 0.4,
  });
  const pole = new THREE.Mesh(poleGeo, poleMat);
  pole.name = 'pole';
  pole.position.set(0.0, 1.0, 0.0);

  // Housing: box sitting near the top of the pole, offset on x.
  const housingGeo = new THREE.BoxGeometry(0.6, 0.6, 0.6);
  const housingMat = new THREE.MeshStandardMaterial({
    name: 'HousingMaterial',
    color: new THREE.Color(0.75, 0.15, 0.12), // lacquer red
    metalness: 0.1,
    roughness: 0.7,
  });
  const housing = new THREE.Mesh(housingGeo, housingMat);
  housing.name = 'housing';
  housing.position.set(0.25, 2.3, 0.0);

  // Bulb: glowing sphere inside/above the housing, offset on z.
  const bulbGeo = new THREE.SphereGeometry(0.22, 16, 12);
  const bulbMat = new THREE.MeshStandardMaterial({
    name: 'BulbMaterial',
    color: new THREE.Color(0.95, 0.85, 0.45), // warm amber glow
    metalness: 0.0,
    roughness: 0.2,
  });
  const bulb = new THREE.Mesh(bulbGeo, bulbMat);
  bulb.name = 'bulb';
  bulb.position.set(0.25, 2.3, 0.4);

  root.add(pole, housing, bulb);
  return root;
}

