import * as THREE from 'three';
import { GLTFExporter } from 'three/examples/jsm/exporters/GLTFExporter.js';

/**
 * Node polyfills for GLTFExporter. The exporter touches a handful of
 * browser-only globals depending on code path. We export non-binary glTF
 * (JSON with embedded base64 buffers), which needs:
 *   - btoa / atob            : available natively in modern Node, but
 *                              polyfilled defensively below.
 *   - FileReader             : only used for images/canvas in the exporter;
 *                              we provide a minimal stub so any accidental
 *                              reference fails loudly instead of crashing.
 *   - TextEncoder/TextDecoder: native in Node.
 *   - Blob / URL.createObjectURL: only used on the binary path; not needed
 *                              here but stubbed for safety.
 */

if (typeof globalThis.btoa !== 'function') {
  globalThis.btoa = (str) => Buffer.from(str, 'binary').toString('base64');
}
if (typeof globalThis.atob !== 'function') {
  globalThis.atob = (b64) => Buffer.from(b64, 'base64').toString('binary');
}
if (typeof globalThis.FileReader !== 'function') {
  // Minimal stub: exporter only needs it for texture images, which this
  // project does not use. Fail loudly if it is ever invoked.
  globalThis.FileReader = class FileReaderStub {
    readAsDataURL() {
      throw new Error('FileReader stub: image export is not supported in Node');
    }
  };
}
if (typeof globalThis.self === 'undefined') {
  globalThis.self = globalThis;
}

/**
 * Exports `object` as non-binary glTF (a plain JSON object with embedded
 * data-URI buffers).
 *
 * @param {THREE.Object3D} object
 * @returns {Promise<object>} parsed glTF JSON document
 */
export function exportToGLTF(object) {
  return new Promise((resolve, reject) => {
    const exporter = new GLTFExporter();
    exporter.parse(
      object,
      (gltf) => resolve(gltf),
      (error) => reject(error),
      { binary: false }
    );
  });
}

