/**
 * Minimal glTF importer - hand-written, no GLTFLoader.
 *
 * Supports exactly the subset produced by src/export.js:
 *   - JSON glTF (binary: false) with embedded base64 data-URI buffers
 *   - nodes with translation/rotation/scale/matrix, children, meshes
 *   - meshes -> primitives -> attributes.POSITION / indices
 *   - accessors referencing bufferViews (honouring bufferView.byteOffset,
 *     accessor.byteOffset and all standard componentTypes, notably 5126 FLOAT)
 *   - materials -> baseColorFactor mapped onto MeshStandardMaterial
 */

const COMPONENT_TYPE = {
  5120: { array: Int8Array, bytes: 1 }, // BYTE
  5121: { array: Uint8Array, bytes: 1 }, // UNSIGNED_BYTE
  5122: { array: Int16Array, bytes: 2 }, // SHORT
  5123: { array: Uint16Array, bytes: 2 }, // UNSIGNED_SHORT
  5125: { array: Uint32Array, bytes: 4 }, // UNSIGNED_INT
  5126: { array: Float32Array, bytes: 4 }, // FLOAT
};

const TYPE_COUNT = {
  SCALAR: 1,
  VEC2: 2,
  VEC3: 3,
  VEC4: 4,
  MAT2: 8,
  MAT3: 9,
  MAT4: 16,
};

/** Decode an embedded data URI ("data:application/octet-stream;base64,...") into raw bytes. */
function decodeDataURI(uri) {
  const marker = 'base64,';
  const idx = uri.indexOf(marker);
  if (idx === -1) {
    throw new Error(`Unsupported buffer uri (not embedded base64): ${uri}`);
  }
  return Buffer.from(uri.slice(idx + marker.length), 'base64');
}

/** Read one accessor out of the glTF document as a flat typed array. */
function readAccessor(gltf, buffers, accessorIndex) {
  const accessor = gltf.accessors[accessorIndex];
  if (accessor.bufferView === undefined) {
    throw new Error(`Accessor ${accessorIndex} has no bufferView (sparse not supported)`);
  }
  const bufferView = gltf.bufferViews[accessor.bufferView];
  const compInfo = COMPONENT_TYPE[accessor.componentType];
  if (!compInfo) throw new Error(`Unsupported componentType ${accessor.componentType}`);

  const numComponents = TYPE_COUNT[accessor.type];
  if (!numComponents) throw new Error(`Unsupported accessor type ${accessor.type}`);

  const buffer = buffers[bufferView.buffer];
  if (!(buffer instanceof Buffer)) throw new Error('bufferView does not point at decoded Buffer');

  // Absolute byte offset of this accessor's first element:
  // buffer start + bufferView offset + accessor offset.
  const viewOffset = bufferView.byteOffset ?? 0;
  const accessorOffset = accessor.byteOffset ?? 0;
  const stride = bufferView.byteStrinde ?? undefined; // placeholder, fixed below
  const byteStride =
    bufferView.byteStride !== undefined && bufferView.byteStride !== 0
      ? bufferView.byteStride
      : numComponents * compInfo.bytes;

  const elemStride = Math.max(byteStride, numComponents * compInfo.bytes);

  const out = new compInfo.array(accessor.count * numComponents);
  const tmp = new compInfo.array(1);
  const littleEndian = true;

  for (let e = 0; e < accessor.count; e++) {
    const elemStart = viewOffset + accessorOffset + e * elemStride;
    for (let c = 0; c < numComponents; c++) {
      const byteOffset = elemStart + c * compInfo.bytes;
      switch (accessor.componentType) {
        case 5126:
          out[e * numComponents + c] = buffer.readFloatLE(byteOffset);
          break;
        case 5125:
          out[e * numComponents + c] = buffer.readUInt32LE(byteOffset);
          break;
        case 5123:
          out[e * numComponents + c] = buffer.readUInt16LE(byteOffset);
          break;
        case 5122:
          out[e * numComponents + c] = buffer.readInt16LE(byteOffset);
          break;
        case 5121:
          out[e * numComponents + c] = buffer.readUInt8(byteOffset);
          break;
        case 5120:
          out[e * numComponents + c] = buffer.readInt8(byteOffset);
          break;
        default:
          throw new Error(`Unhandled componentType ${accessor.componentType}`);
      }
      void tmp;
      void littleEndian;
    }
  }

  // Normalized integer accessors are scaled to [0,1]/[-1,1]; positions are
  // never normalized in practice, so we only warn.
  if (accessor.normalized) {
    // eslint-disable-next-line no-console
    console.warn(`Accessor ${accessorIndex} is normalized; values returned unscaled`);
  }

  return out;
}

/** Rebuild a THREE.BufferGeometry from a primitive's POSITION (and indices if present). */
function buildGeometry(gltf, buffers, primitive) {
  const geometry = new (gltf.__three ?? require('three')).BufferGeometry();
  return geometry;
}

import * as THREE from 'three';

function buildPrimitiveGeometry(gltf, buffers, primitive) {
  const geometry = new THREE.BufferGeometry();

  if (primitive.attributes?.POSITION !== undefined) {
    const pos = readAccessor(gltf, buffers, primitive.attributes.POSITION);
    geometry.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  } else {
    throw new Error('Primitive is missing POSITION; this subset requires it');
  }

  if (primitive.indices !== undefined) {
    const idx = readAccessor(gltf, buffers, primitive.indices);
    geometry.setIndex(new THREE.BufferAttribute(idx, 1));
  }

  return geometry;
}

/** Map a glTF material to a THREE.MeshStandardMaterial (baseColorFactor only). */
function buildMaterial(gltf, materialIndex) {
  if (materialIndex === undefined || !gltf.materials?.[materialIndex]) {
    return new THREE.MeshStandardMaterial();
  }
  const src = gltf.materials[materialIndex];
  const pbr = src.pbrMetallicRoughness ?? {};
  const mat = new THREE.MeshStandardMaterial();
  if (pbr.baseColorFactor) {
    mat.color.setRGB(
      pbr.baseColorFactor[0],
      pbr.baseColorFactor[1],
      pbr.baseColorFactor[2],
      THREE.SRGBColorSpace === undefined ? undefined : 'srgb'
    );
  }
  if (pbr.metallicFactor !== undefined) mat.metalness = pbr.metallicFactor;
  if (pbr.roughnessFactor !== undefined) mat.roughness = pbr.roughnessFactor;
  if (src.name) mat.name = src.name;
  return mat;
}

function applyNodeTransform(object, nodeDef) {
  if (nodeDef.matrix) {
    const m = new THREE.Matrix4().fromArray(nodeDef.matrix);
    m.decompose(object.position, object.quaternion, object.scale);
  } else {
    if (nodeDef.translation) object.position.fromArray(nodeDef.translation);
    if (nodeDef.rotation) object.quaternion.fromArray(nodeDef.rotation);
    if (nodeDef.scale) object.scale.fromArray(nodeDef.scale);
  }
  object.updateMatrix();
}

/** Recursively instantiate a node definition into a THREE.Object3D tree. */
function buildNode(gltf, buffers, nodeIndex) {
  const nodeDef = gltf.nodes[nodeIndex];

  let object;
  if (nodeDef.mesh !== undefined) {
    const meshDef = gltf.meshes[nodeDef.mesh];
    if (meshDef.primitives.length === 1) {
      const prim = meshDef.primitives[0];
      const geo = buildPrimitiveGeometry(gltf, buffers, prim);
      const mat = buildMaterial(gltf, prim.material);
      object = new THREE.Mesh(geo, mat);
      object.userData.primitive = prim;
    } else {
      // One Object3D per primitive, grouped under the node transform.
      object = new THREE.Group();
      for (const prim of meshDef.primitives) {
        const geo = buildPrimitiveGeometry(gltf, buffers, prim);
        const mat = buildMaterial(gltf, prim.material);
        const mesh = new THREE.Mesh(geo, mat);
        mesh.userData.primitive = prim;
        object.add(mesh);
      }
    }
  } else {
    object = new THREE.Group();
  }

  object.name = nodeDef.name ?? `node_${nodeIndex}`;
  applyNodeTransform(object, nodeDef);

  for (const childIndex of nodeDef.children ?? []) {
    object.add(buildNode(gltf, buffers, childIndex));
  }
  return object;
}

/**
 * Parse a glTF JSON document (as produced by exportToGLTF) into a THREE scene.
 * @param {object} gltf parsed glTF JSON
 * @returns {{ scene: THREE.Object3D, gltf: object }}
 */
export function importGLTF(gltf) {
  if (!gltf.asset || gltf.asset.version !== '2.0') {
    throw new Error('Not a glTF 2.0 document');
  }

  // Decode every buffer up front.
  const buffers = (gltf.buffers ?? []).map((b) => {
    if (!b.uri) throw new Error('External .bin buffers are not supported');
    return decodeDataURI(b.uri);
  });

  const sceneIndex = gltf.scene ?? 0;
  const rootNodes = gltf.scenes[sceneIndex].nodes;

  // A single root container keeps multiple top-level nodes together.
  const scene = new THREE.Group();
  scene.name = gltf.scenes[sceneIndex].name ?? 'scene';
  for (const nodeIndex of rootNodes) {
    scene.add(buildNode(gltf, buffers, nodeIndex));
  }

  void buildGeometry; // kept for API symmetry; real work happens in buildPrimitiveGeometry

  return { scene, gltf };
}

