import { describe, it, expect, beforeAll } from 'vitest';
import * as THREE from 'three';

import { buildLantern } from '../src/model.js';
import { exportToGLTF } from '../src/export.js';
import { importGLTF } from '../src/importer.js';

let originalRoot;
let gltf;
let reimported;

/** Collect (object, depth) pairs in depth-first order. */
function flatten(root) {
  const out = [];
  root.traverse((o) => out.push(o));
  return out;
}

function hierarchyDepth(root) {
  let max = 0;
  root.traverse((o) => {
    let d = 0;
    for (let p = o; p !== root; p = p.parent) d++;
    max = Math.max(max, d);
  });
  return max;
}

function collectMeshes(root) {
  const meshes = [];
  root.traverse((o) => {
    if (o.isMesh && o.geometry?.getAttribute('position')) {
      meshes.push(o);
    }
  });
  return meshes;
}

beforeAll(async () => {
  originalRoot = buildLantern();
  gltf = await exportToGLTF(originalRoot);
  reimported = importGLTF(gltf).scene;
});

describe('glTF round-trip with minimal importer', () => {
  it('produces a valid non-binary glTF document', () => {
    expect(gltf.asset?.version).toBe('2.0');
    // Non-binary: no top-level binary chunk, buffers embedded as data URIs.
    expect(Array.isArray(gltf.buffers)).toBe(true);
    for (const b of gltf.buffers) {
      expect(b.uri).toMatch(/^data:application\/octet-stream;base64,/);
    }
  });

  it('reimported tree has the same node count and hierarchy depth', () => {
    const origNodes = flatten(originalRoot);
    const newNodes = flatten(reimported);

    expect(newNodes.length).toBe(origNodes.length);

    const origDepth = hierarchyDepth(originalRoot);
    const newDepth = hierarchyDepth(reimported);
    expect(newDepth).toBe(origDepth);
    // Sanity: lantern is group -> mesh, i.e. depth 1.
    expect(origDepth).toBe(1);

    // Names line up position-by-position.
    expect(newNodes.map((n) => n.name)).toEqual(origNodes.map((n) => n.name));
  });

  it('each rebuilt geometry has the same position count as the original', () => {
    const origMeshes = collectMeshes(originalRoot);
    const newMeshes = collectMeshes(reimported);
    expect(newMeshes.length).toBe(origMeshes.length);

    const byName = Object.fromEntries(newMeshes.map((m) => [m.name, m]));
    for (const orig of origMeshes) {
      const rebuilt = byName[orig.name];
      expect(rebuilt, `missing rebuilt mesh '${orig.name}'`).toBeDefined();
      expect(rebuilt.geometry.getAttribute('position').count).toBe(
        orig.geometry.getAttribute('position').count
      );
    }
  });

  it('world-space Box3 of original and reimport agree within 1e-4', () => {
    originalRoot.updateMatrixWorld(true);
    reimported.updateMatrixWorld(true);

    const boxA = new THREE.Box3().setFromObject(originalRoot);
    const boxB = new THREE.Box3().setFromObject(reimported);

    expect(boxB.min.x).toBeCloseTo(boxA.min.x, 4);
    expect(boxB.min.y).toBeCloseTo(boxA.min.y, 4);
    expect(boxB.min.z).toBeCloseTo(boxA.min.z, 4);
    expect(boxB.max.x).toBeCloseTo(boxA.max.x, 4);
    expect(boxB.max.y).toBeCloseTo(boxA.max.y, 4);
    expect(boxB.max.z).toBeCloseTo(boxA.max.z, 4);

    // Also verify vertex-accurate bounds per mesh, not just object bounds.
    const origMeshes = collectMeshes(originalRoot);
    const newMeshes = collectMeshes(reimported);
    const byName = Object.fromEntries(newMeshes.map((m) => [m.name, m]));
    for (const orig of origMeshes) {
      const a = orig.geometry.getAttribute('position');
      const b = byName[orig.name].geometry.getAttribute('position');
      for (let i = 0; i < a.count * 3; i++) {
        if (Number.isFinite(a.array[i]) && Number.isFinite(b.array[i])) {
          // Positions may be quantized only if exporter did so (it does not
          // by default), so they must match exactly here.
          expect(b.array[i]).toBeCloseTo(a.array[i], 6);
        }
      }
    }
  });

  it('per-node translations match within 1e-6', () => {
    const origNodes = flatten(originalRoot);
    const newNodes = flatten(reimported);
    expect(newNodes.length).toBe(origNodes.length);

    for (let i = 0; i < origNodes.length; i++) {
      const a = origNodes[i];
      const b = newNodes[i];
      expect(b.position.x).toBeCloseTo(a.position.x, 6);
      expect(b.position.y).toBeCloseTo(a.position.y, 6);
      expect(b.position.z).toBeCloseTo(a.position.z, 6);
    }
  });

  it('material baseColorFactor round-trips for each part within 1e-4', () => {
    // Check at both levels: raw JSON factors and rebuilt three materials.
    const origMeshes = collectMeshes(originalRoot);
    const newMeshes = collectMeshes(reimported);
    const byName = Object.fromEntries(newMeshes.map((m) => [m.name, m]));

    for (const orig of origMeshes) {
      const rebuilt = byName[orig.name];
      const c0 = orig.material.color;
      const c1 = rebuilt.material.color;
      expect(c1.r).toBeCloseTo(c0.r, 4);
      expect(c1.g).toBeCloseTo(c0.g, 4);
      expect(c1.b).toBeCloseTo(c0.b, 4);

      // Cross-check against the baseColorFactor actually written to JSON.
      const matIndex = rebuilt.userData.primitive.material;
      const factor = gltf.materials[matIndex].pbrMetallicRoughness.baseColorFactor;
      expect(factor[0]).toBeCloseTo(c0.r, 4);
      expect(factor[1]).toBeCloseTo(c0.g, 4);
      expect(factor[2]).toBeCloseTo(c0.b, 4);
      expect(factor[3]).toBeCloseTo(1, 4);
    }
  });
});

