if (typeof globalThis.FileReader !== 'function') {
  // Minimal FileReader covering exactly what GLTFExporter needs on the
  // non-binary path: readAsDataURL / readAsArrayBuffer on a Blob.
  globalThis.FileReader = class FileReader {
    constructor() {
      this.result = null;
      this.onloadend = null;
    }
    _finish(result) {
      this.result = result;
      // Async like the browser, so exporter code can assign onloadend first.
      queueMicrotask(() => this.onloadend && this.onloadend());
    }
    readAsDataURL(blob) {
      blob
        .arrayBuffer()
        .then((ab) =>
          this._finish(
            `data:${blob.type || 'application/octet-stream'};base64,${Buffer.from(ab).toString('base64')}`
          )
        );
    }
    readAsArrayBuffer(blob) {
      blob.arrayBuffer().then((ab) => this._finish(ab));
    }
  };
}

